__NUXT_JSONP__("/ar/havevisa", (function(a){return {data:[{details:{slug:"ar",pageTitle:"How to apply if you have a U.S. VISA | Mentor Language Institute",pageDescription:a,title:"How to apply if you have a U.S. VISA",image:"\u002Fimages\u002Fhavevisa\u002Fattraction.png",category:[{title:a,content:["-Apply from Outside of the U.S\u003Cbr \u002F\u003E-Applicants who have stayed in the U.S. and have an F1 Visa\u003Cbr \u002F\u003E-Applicants who have studied in the U.S. within the past 5 months","※You need to get an F1 VISA again if it's been more than 5 months since you finished at a previous school."]},{title:"Application Steps",image:"\u002Fimages\u002Fhavevisa\u002Fmli-design-apply-short-kr.jpg",ordered_content:["Apply to MLI","Submit the documents","Receive your I-20","Leave for the U.S."],content:["If you have a valid U.S. visa , you don't have to get a new VISA. Bring your I-20 and vaild U.S. VISA and fly to the US.","Students are required to apply 1 or 2 months before desired starting date. It is best to speak with front desk staff after applying to confirm the application process as it can be complicated depending on your status."]},{title:"Cancellation Policy",content:["The enrollment fee of $150, will be charged at the time of application. The enrollment fee is non-refundable regardless if an application is rejected or enrollment is cancelled. Exceptions include insufficient housing."]},{title:"About the steps after application",image:"\u002Fimages\u002Fhavevisa\u002Fmli-short-en.jpg",content:["After students have applied, the iMLI system processes the application.\u003Cbr \u002F\u003EStudents can follow the process which is listed on the iMLI."],types:[{title:"Apply Online",content:["Fill out the information about your visa status \u003Cbr \u002F\u003EContact us via iMLI for all inquiries","Apply from below."]}]}],btn_label:"Online application Form",admission:{link:"\u002Far\u002Fadmission",content:["*Please have your credit card in hand."]},dir:"\u002Fhavevisa",path:"\u002Fhavevisa\u002Far",extension:".json",createdAt:"2026-10-22T16:31:29.452Z",updatedAt:"2025-05-26T12:06:27.775Z"}}],fetch:{},mutations:void 0}}("Applicants from Outside of the U.S. who have a U.S. VISA")));